#pragma once

#include <Arduino.h>

/** Real 320x320 baseline JPEG covers for ID3 APIC (generated by scripts/gen_covers.ps1). */
namespace CoverJpegs {

struct Cover {
    const uint8_t* data;
    uint32_t len;
};

static constexpr uint8_t kCount = 4;
extern const Cover kCovers[kCount];

/** cover 1..kCount → JPEG, else nullptr. */
inline const Cover* get(uint8_t cover) {
    return (cover >= 1 && cover <= kCount) ? &kCovers[cover - 1] : nullptr;
}

/** APIC slot that fits every cover, so a live cover swap never changes the file size. */
inline uint32_t slotBytes() {
    uint32_t m = 0;
    for (uint8_t i = 0; i < kCount; i++) m = kCovers[i].len > m ? kCovers[i].len : m;
    return (m + 511u) & ~511u;
}

}  // namespace CoverJpegs
